// ====================================================================
// PLAN CLEANUP - STATS housekeeping tiap 3 bulan
//
// ATURAN: SEMUA baris dihapus KECUALI off_reason == "SAM".
// Perbandingan case-insensitive + trim, jadi "SAM", "Sam", "sam",
// dan " SAM " sama-sama dipertahankan. Baris SAM = murid/parent yang
// di-OFF-kan Sam sendiri dan harus ditangani manual selamanya.
//
// STRATEGI AMAN (urutan ini disengaja, JANGAN dibalik):
//   1. salin baris SAM ke BAWAH sheet dulu (append)
//   2. baru hapus blok baris asli di atasnya (delete)
// Kalau append gagal -> belum ada yang dihapus -> nol kehilangan data.
// Kalau delete gagal -> cuma duplikat -> masih nol kehilangan data.
// Kalau urutannya dibalik, satu kegagalan append = baris murid Sam
// hilang permanen.
// ====================================================================

const KEEP_VALUE = 'SAM';
const norm = v => String(v ?? '').trim().toUpperCase();

const rows = $input.all()
  .map(i => i.json)
  .filter(r => r && typeof r === 'object'
            && r.row_number !== undefined
            && Number(r.row_number) >= 2);

if (!rows.length) {
  console.log('STATS kosong / hanya header - tidak ada yang dibersihkan.');
  return [];
}

// Guard 1: pastikan yang terbaca benar-benar tab STATS.
// Kalau kolom kuncinya tidak ada, BERHENTI dengan error - lebih baik
// workflow gagal berisik daripada menghapus tab yang salah.
const sample = rows[0];
if (!('No WA' in sample)) {
  throw new Error('Kolom "No WA" tidak ditemukan - tab yang terbaca kemungkinan bukan STATS. Cleanup DIBATALKAN.');
}

// Guard 2: kolom off_reason wajib sudah ada. Tanpa kolom ini semua
// baris akan terbaca sebagai non-SAM dan murid/parent Sam ikut terhapus.
if (!('off_reason' in sample)) {
  throw new Error('Kolom "off_reason" belum ada di STATS. Tambahkan kolomnya dulu sebelum mengaktifkan workflow ini. Cleanup DIBATALKAN.');
}

const keptRows = [];
let offByVira = 0;
let offNoLabel = 0;

for (const r of rows) {
  if (norm(r.off_reason) === KEEP_VALUE) {
    const copy = { ...r };
    delete copy.row_number;  // kolom bawaan n8n, bukan kolom asli sheet
    keptRows.push(copy);
  } else if (norm(r.bot_mode) === 'OFF') {
    if (norm(r.off_reason) === 'VIRA') offByVira++;
    else offNoLabel++;
  }
}

// Rentang hapus dihitung dari row_number TERBESAR, bukan rows.length,
// supaya baris kosong di tengah (kalau ada) ikut kena hapus dan hasil
// akhirnya rapi tanpa celah.
const maxRow = rows.reduce((m, r) => Math.max(m, Number(r.row_number)), 0);
const totalDataRows = maxRow - 1;

if (totalDataRows < 1) {
  console.log('Tidak ada baris data untuk dibersihkan.');
  return [];
}

const keptCount = keptRows.length;
const deleteCount = totalDataRows - keptCount;

console.log(`STATS cleanup: ${totalDataRows} baris data | ${keptCount} SAM dipertahankan | ${deleteCount} dihapus (OFF by VIRA: ${offByVira}, OFF tanpa label: ${offNoLabel}).`);

return [{
  json: {
    startRow: 2,
    totalDataRows,
    keptCount,
    deleteCount,
    offByVira,
    offNoLabel,
    keptRows,
  }
}];

// Pecah keptRows jadi item terpisah supaya node Append menulis
// satu baris per item. row_number sudah dibuang di Plan cleanup.
const plan = $('Plan cleanup').first().json;
const rows = plan.keptRows || [];

if (!rows.length) {
  console.log('Tidak ada baris SAM untuk disalin.');
  return [];
}

console.log(`Menyalin ${rows.length} baris SAM ke bawah sebelum blok lama dihapus.`);
return rows.map(r => ({ json: r }));

// Node ini WAJIB mengeluarkan TEPAT 1 item.
// Node Google Sheets jalan sekali per item masuk - kalau node Append
// mengirim 30 item ke sini tanpa diciutkan, node Delete akan jalan
// 30x dan menghapus blok yang salah berkali-kali.
const plan = $('Plan cleanup').first().json;
const last = plan.startRow + plan.totalDataRows - 1;

console.log(`Hapus blok asli: baris ${plan.startRow}..${last} (${plan.totalDataRows} baris). Salinan SAM sudah aman di bawahnya.`);

return [{ json: plan }];
